nt="Nevada reports HS math/ELA via ACT (grade 11) and science via the Nevada HS science assessment, with NSPF-style binning: values >95 and <5 are published as such (top/bottom coded). Portal 'year' 2024 = school year 2023-24 (NSPF PDF for the same year is titled School Year 2023-2024). Dashboard field names reading_high/math_high are the portal's high school proficiency fields; the portal did not state the exact proficiency threshold name in the fields read."
for yr,lab,fy in [(2024,"2023-24","2023-24"),(2025,"2024-25","2024-25")]:
    for fld,name in [("math_high","Mathematics (high school, ACT grade 11-based)"),("reading_high","Reading/ELA (high school, ACT grade 11-based)")]:
        nv.append(f(f"{lab} {name} percent proficient, all students",">95",lab,da%yr,f"files/NV/dashboard-api/dashboard-65758-{yr}.json",f"JSON field {fld}, orgId 65758 (code 84406)",nt))
    nv.append(f(f"{lab} Science proficiency, school rate (NSPF school rating page)",">95",lab,f"{N}DI/nspf/84406/{yr}/pdf",f"files/NV/nspf-84406-{yr}/nspf-84406-{yr}.pdf",f"Page 1, '{lab} School Performance' table, row Science Proficiency (School Rate >95, District Rate >95)","Binned top-coded value as published. NSPF measure covers the school as rated (School Level listed as Middle School, grades 05-12 in 2023-24 and 06-12 in 2024-25), not high school grades only. Also in that table: Math Proficiency >95, ELA Proficiency >95, Pooled Proficiency >95."))
    nv.append(f(f"{lab} Four-year adjusted cohort graduation rate (portal field gradrate / total_PctGradRate)",">95",lab,da%yr,f"files/NV/dashboard-api/dashboard-65758-{yr}.json","JSON fields gradrate and total_PctGradRate; total_PctGradRate_5yr also >95","Binned top-coded. Portal lists cohort graduation under 'Reported for Prior School Year', so the portal 'year' %d may refer to the class of %d or %d; cohort-year labelling not resolved from the fields read. Class-of-2024 figure is therefore best matched to portal year 2024 or 2025 - confirm before use."%(yr,yr,yr-1)))
nv.append(f("2023-24 Economically disadvantaged percent (portal field sP_PctEnrFRL)","N/A","2023-24",da%2024,"files/NV/dashboard-api/dashboard-65758-2024.json","JSON field sP_PctEnrFRL","State label in field: FRL (free/reduced lunch); NSPF PDF 2023-24 shows an Econ Disadv bar chart without a numeric label in extracted text. Not published as a number in what was read."))
